public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) return -1;

    // Initialize the largest substring to be a valid string
    String largestSubstring = "";
    for (String string : strings) {
        if (string.length() > largestSubstring.length()) {
            largestSubstring = string;
        }
    }

    // If the largest substring is the empty string, return -1
    if (largestSubstring.isEmpty()) return -1;

    // Loop through each string and check if the largest substring is a substring
    for (String string : strings) {
        if (string.contains(largestSubstring) || largestSubstring.contains(string)) {
            // If the substring is found, return the length of the largest substring
            return largestSubstring.length();
        }
    }

    // If the largest substring is not found in any of the strings, return -1
    return -1;
}

