    // If no such string exists, return -1.
    int largest = -1;
    for (String s : strings) {
        // Check if the string's inverse is a substring of any of the input strings.
        if (strings.stream().anyMatch(t -> t.contains(s.replace("A", "Z").replace("Z", "A")))) {
            largest = Math.max(largest, s.length());
        }
    }
    return largest == -1 ? -1 : largest;
}

