public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    Set<String> visited = new HashSet<>();
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (visited.contains(Arrays.toString(current))) {
            continue;
        }
        visited.add(Arrays.toString(current));
        for (int[] path : paths) {
            int[] next = {current[0] + path[0], current[1] + path[1]};
            if (next[0] < 0 || next[0] >= n || next[1] < 0 || next[1] >= n) {
                continue;
            }
            if (Arrays.equals(next, end)) {
                return "can be travelled";
            }
            queue.offer(next);
        }
    }
    return "cannot be travelled";
}

