public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1 || n / 2 < k) {
        return false;
    }

    int[] sums = new int[k];
    for (int i = 0; i < n; i++) {
        int j = i % 2 == 0 ? i / 2 : (i + 1) / 2;
        sums[j] += arr[i];
    }

    for (int sum : sums) {
        if (sum % k != 0) {
            return false;
        }
    }

    return true;
}

