    // Initialize a boolean array visited to keep track of visited nodes
    boolean[] visited = new boolean[n];

    // Set the starting node to 0
    int currentNode = 0;

    // Initialize a queue to perform BFS
    Queue<Integer> queue = new LinkedList<Integer>();

    // Initialize a variable to keep track of the time
    int time = 0;

    // Add the starting node to the queue
    queue.add(currentNode);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the size of the queue
        int size = queue.size();

        // Loop through each node in the queue
        for (int i = 0; i < size; i++) {
            // Get the current node
            currentNode = queue.poll();

            // If the current node has an apple and has not been visited, add it to the visited array and reset the time
            if (hasApple[currentNode] && !visited[currentNode]) {
                visited[currentNode] = true;
                time = 0;
            }

            // If the current node is not visited, add it to the queue and increment the time
            if (!visited[currentNode]) {
                queue.add(currentNode);
                time++;
            }
        }
    }

    // Return the minimum time required to collect all apples
    return time;
}

