public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a priority queue to store nodes based on their distance from node 0
    PriorityQueue<Node> queue = new PriorityQueue<Node>(Comparator.comparingInt(node -> node.distance));

    // Mark node 0 as visited and add it to the priority queue
    boolean[] visited = new boolean[n];
    visited[0] = true;
    queue.add(new Node(0, 0, 1));

    while (!queue.isEmpty()) {
        // Extract the node with the minimum distance from the priority queue
        Node current = queue.poll();

        // If the current node has an apple, return the distance traveled
        if (hasApple[current.index]) {
            return current.distance;
        }

        // For each neighbor of the current node that has not been visited, mark it as visited and add it to the priority queue
        for (int i = 0; i < edges[current.index].length; i++) {
            int neighbor = edges[current.index][i];
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(new Node(neighbor, current.distance + 1));
            }
        }
    }

    // If no apple is found, return 0
    return 0;
}

