public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the graph and the collected apples set
    int[][] graph = new int[n][n];
    int[] collectedApples = new int[n];
    Arrays.fill(collectedApples, 0);

    // Populate the graph and the edge weights
    for (int i = 0; i < edges.length; i++) {
        int[] edge = edges[i];
        int start = edge[0];
        int end = edge[1];
        int weight = 1;
        if (hasApple[i]) {
            weight = 2;
        }
        graph[start][end] = weight;
        graph[end][start] = weight;
    }

    // Perform BFS and collect apples
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    collectedApples[0] = 1;
    while (!queue.isEmpty()) {
        int current = queue.poll();
        for (int i = 0; i < n; i++) {
            if (graph[current][i] > 0 && collectedApples[i] == 0) {
                collectedApples[i] = collectedApples[current] + 1;
                queue.add(i);
            }
        }
    }

    // Calculate the minimum time needed to collect all the apples
    int minTime = collectedApples[n - 1];
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime = Math.min(minTime, collectedApples[i]);
        }
    }
    return minTime;
}

