public static int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 1) return 0;
    // Create a graph from the edge list
    int[][] graph = new int[n][n];
    for (int[] edge : edges) {
        graph[edge[0]][edge[1]] = 1;
        graph[edge[1]][edge[0]] = 1;
    }

    // Do a breadth-first search to get the distance from node 0 to all other nodes
    int[] distance = new int[n];
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    distance[0] = 1;
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor = 0; neighbor < n; neighbor++) {
            if (graph[node][neighbor] == 1 && distance[neighbor] == 0) {
                distance[neighbor] = distance[node] + 1;
                queue.offer(neighbor);
            }
        }
    }

    // Get the maximum distance
    int maxDistance = 0;
    for (int d : distance) {
        maxDistance = Math.max(maxDistance, d);
    }

    // If we can't reach all nodes from node 0, return -1
    if (maxDistance == 0) {
        return -1;
    }

    // If a node has an apple, add its distance from node 0 to the cost
    int cost = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && distance[i] > 0) {
            cost += distance[i];
        }
    }

    return cost;
}

