public String sortString(String s) {

    String sortedString = "";
    Map<Character, Integer> charCounts = new HashMap<>();
    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        charCounts.put(currentChar, charCounts.getOrDefault(currentChar, 0) + 1);
    }

    while (sortedString.length() < s.length()) {
        // Sort characters by count
        List<Character> sortedChars = charCounts.keySet()
            .stream()
            .sorted(Comparator.comparingInt(c -> charCounts.get(c)))
            .collect(Collectors.toList());

        // Add smallest character
        Character smallestChar = sortedChars.get(0);
        charCounts.put(smallestChar, charCounts.get(smallestChar) - 1);
        sortedString += smallestChar;

        // Add largest character
        Character largestChar = sortedChars.get(sortedChars.size() - 1);
        charCounts.put(largestChar, charCounts.get(largestChar) - 1);
        sortedString = largestChar + sortedString;
    }

    return sortedString;
}

