public int kthFactor(int n, int k) {
    // Check if k is a valid input
    if (k < 1) {
        throw new IllegalArgumentException("k must be a positive integer");
    }

    // Initialize a set to store the factors of n
    Set<Integer> factors = new HashSet<>();

    // Iterate from 1 to n and check if each number is a factor of n
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
