    for (int i = 1; i <= numDigits; i++) {
        int digit = n % 10;
        n /= 10;
        if (i % 3 == 0 && i != numDigits) {
            sb.insert(0, ".");
        }
        sb.insert(0, digit);
    }
    return sb.toString();
}

